const fs=require('node:fs');
const assert=require('node:assert/strict');
const read=path=>fs.readFileSync(path,'utf8');
const dashboard=read('public/dashboard-discovery.js');
const dashboardCss=read('public/dashboard-discovery.css');
const profileCard=read('public/profile-card.js');
const members=read('public/members.js');
const membersHtml=read('public/members.html');
const membersApi=read('src/members.ts');
const worker=read('src/worker.ts');
const shell=read('public/site-shell.js');
const migration=read('migrations/20260721_dashboard_calendar_clock_members.sql');
new Function(dashboard);
new Function(profileCard);
new Function(members);
assert.match(dashboard,/feature-module-calendar/);
assert.match(dashboard,/dashboard-calendar-grid/);
assert.match(dashboard,/Nothing scheduled today/);
assert.match(dashboard,/dashboard-open-tile-picker/);
assert.match(dashboard,/Choose a tile to add/);
assert.match(dashboard,/renderCatalogue\(\)/);
assert.match(dashboard,/installPickerRouting/);
assert.match(dashboard,/scheduleSync/);
assert.match(dashboard,/MutationObserver\(syncPickerState\)/);
assert.match(dashboard,/dashboard:editor-opened/);
assert.match(dashboard,/body\.append\(catalogue\)/);
assert.doesNotMatch(dashboard,/openEditor=function discoveryOpenEditor/);
assert.match(dashboard,/CATEGORY_LABELS/);
assert.match(dashboard,/dashboard-category-navigation/);
assert.match(dashboard,/dashboard-catalogue-category-grid/);
assert.match(dashboard,/Planning & personal/);
assert.match(dashboard,/Community & social/);
assert.match(dashboard,/installAutomaticDeviceLayout/);
assert.match(dashboard,/grev-dashboard-layout-mode/);
assert.match(dashboard,/media\.addEventListener\('change', applyActualMode\)/);
assert.match(dashboard,/Automatic ·/);
assert.match(dashboardCss,/\.dashboard-device-switch\{display:none!important\}/);
assert.match(dashboardCss,/\.dashboard-category-navigation/);
assert.match(dashboardCss,/\.dashboard-catalogue-category-grid/);
assert.match(profileCard,/function create\(profile, options = \{\}\)/);
assert.match(profileCard,/profile-card-cover/);
assert.match(profileCard,/profile-card-avatar/);
assert.match(profileCard,/applyDesign/);
assert.match(members,/\/api\/members/);
assert.match(members,/GrevProfileCard\.create/);
assert.match(members,/Open full profile/);
assert.doesNotMatch(members,/className='member-card'/);
assert.match(membersHtml,/id="members-grid"/);
assert.match(membersHtml,/href="\/profile\.css"/);
assert.match(membersHtml,/src="\/profile-card\.js"/);
assert.match(membersApi,/cover_media/);
assert.match(membersApi,/website_url/);
assert.match(membersApi,/cardSurface/);
assert.match(membersApi,/showMemberSince/);
assert.match(shell,/href="\/members">Members/);
assert.match(worker,/handleMembersRequest/);
assert.match(worker,/dashboard-discovery\.js/);
assert.match(worker,/url\.pathname === '\/hub' \|\| url\.pathname === '\/members'/);
assert.match(migration,/feature-live-clock/);
assert.match(migration,/feature-module-calendar/);
assert.match(migration,/allowed_dimensions='3x2,4x2,4x3,5x3,6x3,6x4'/);
console.log('Categorised tiles, automatic layouts and the shared permission-aware profile-card directory integration verified.');